    "status.fiveElementsSecret": "Five-Elements Secret Art", "status.windRaccoonBody": "Wind-Raccoon Body", "status.tianGangArmor": "Heavenly-Aegis Armor", "status.mainCharacterHalo": "Main Character Halo", "status.petrify": "Petrification", "status.darkForce": "Hidden Force", "status.burn": "Burn", "status.entangle": "Entangle", "status.swordIntent": "Sword Intent", "status.swordIntentGourd": "Sword Intent Gourd", "status.swordDomain": "Lifeless Sword Domain", "status.eightDirectionsWard": "Eightfold Mountain Ward", "status.clearMind": "Clarity", "status.coldResistance": "Coldproof", "status.steadfast": "Steadfast", "status.heatResistance": "Heatproof", "status.hardness": "Hardened", "status.reflection": "Reflection", "status.undying": "Undying", "status.nirvana": "Nirvana", "status.armorBreak": "Armor Break", "status.heartDemon": "Heart Demon", "status.foresight": "Foresight", "status.qiStagnation": "Qi Stagnation", "status.stun": "Stun", "status.freeze": "Freeze", "status.lostMind": "Lost Mind", "status.barrier": "Barrier", "status.healing": "Healing", "status.concentration": "Concentration",
    "status.info.qi.line1": "Absorbs damage before Stance; 1 Qi blocks 1 damage.", "status.info.qi.line2": "At the holder's turn start, current Qi is halved, rounded down.",
    "status.info.guard.line1": "After Qi, damage at or below Stance is fully blocked.", "status.info.guard.line2": "If exceeded, Stance breaks and only overflow is taken; clears at own turn start.",
    "status.info.burn.line1": "Ignore Qi and Stance; lose 4 HP at the holder's turn end.", "status.info.burn.line2": "After resolving: {downChance}% chance [Burn] -1, {upChance}% chance [Burn] +1.",
    "status.info.entangle.line1": "At turn start, {skipChance}% chance to skip the action. Lose 1 stack at turn end.", "status.info.entangle.line2": "When hit by a fire attack, all stacks convert into [Burn].",
    "status.info.swordIntent.line1": "Each stack gives +1 damage to sword attacks.", "status.info.swordIntent.line2": "[Sword Intent] -1 at the holder's turn end.",
    "status.info.fiveElementsSecret.line1": "A secret art unique to Five-Elements Sect cultivators.", "status.info.fiveElementsSecret.line2": "Adds 25% resistance to Freeze, Burn, Stun, Qi Stagnation, Armor Break, and Entangle, and accelerates Mana flow.", "status.info.windRaccoonBody.line1": "When HP reaches 0, immediately restore {hp} HP. Fails when Mana is depleted.", "status.info.windRaccoonBody.line2": "", "status.info.tianGangArmor.line1": "A protective artifact. At the start of each turn, gain {qi} Qi.", "status.info.tianGangArmor.line2": "", "status.info.mainCharacterHalo.line1": "Hidden effect.", "status.info.mainCharacterHalo.line2": "", "status.info.petrify.line1": "Gain {guard} Stance at turn end.", "status.info.petrify.line2": "", "status.info.darkForce.line1": "Lose 1 stack at turn end.", "status.info.darkForce.line2": "When [Hidden Force] is cleared, lose {damage} HP.", "status.info.swordIntentGourd.line1": "A bonded life artifact unique to Hidden Sword Peak cultivators.", "status.info.swordIntentGourd.line2": "Grants 50% Qi Stagnation resistance and prevents Sword Intent from fading.",
    "status.info.swordDomain.line1": "At turn start, lose {damage}; gain {qi} and {intent}.", "status.info.swordDomain.line2": "", "status.info.eightDirectionsWard.line1": "Gain 8 Qi at turn start.", "status.info.eightDirectionsWard.line2": "", "status.info.clearMind.line1": "50% Stun resistance.", "status.info.clearMind.line2": "50% Heart Demon resistance.", "status.info.coldResistance.line1": "75% Freeze resistance.", "status.info.coldResistance.line2": "Clear [Freeze] at turn end.", "status.info.steadfast.line1": "75% Stun resistance.", "status.info.steadfast.line2": "Clear [Stun] at turn end.", "status.info.heatResistance.line1": "75% Burn resistance, and Burn damage taken is halved.", "status.info.heatResistance.line2": "", "status.info.hardness.line1": "75% Armor Break resistance, and actual damage taken is reduced by 25%.", "status.info.hardness.line2": "", "status.info.reflection.line1": "Reflect {percent}% of actual HP lost back to the attacker.", "status.info.reflection.line2": "Clears at turn start.", "status.info.undying.line1": "When HP reaches 0, immediately restore {hp} HP, clear all statuses, then gain {qi} Qi.", "status.info.undying.line2": "", "status.info.nirvana.line1": "When Burn damage reduces HP to 0, immediately restore 1 HP and clear all statuses.", "status.info.nirvana.line2": "For each [Burn] stack cleared, restore 20 additional HP and gain 2 Mana.",
    "status.info.armorBreak.line1": "While active, Stance is fixed at 0 and cannot be gained; actual damage taken is increased by 50%.", "status.info.armorBreak.line2": "[Armor Break] -1 at turn end.",
    "status.info.heartDemon.line1": "At turn start, Heart Demon may flare up; lower current Sense means a higher chance.", "status.info.heartDemon.line2": "A flare-up disrupts action and causes harm. Afterward, [Heart Demon] -1.",
    "status.info.foresight.line1": "Avoid one enemy attack and its attached statuses.", "status.info.foresight.line2": "[Foresight] -1 at the holder's turn start.",
    "status.info.qiStagnation.line1": "Pause Mana recovery at turn start and accelerate Qi loss.", "status.info.qiStagnation.line2": "Lose 1 stack at turn end.",
    "status.info.stun.line1": "Immediately clears Stance and ends Ghost Flash and Mountain Force. Foresight and Main Character Halo cannot evade; skip action at turn start.", "status.info.stun.line2": "Each [Stun] adds 25% Stun resist; lose 1 at turn end.",
    "status.info.freeze.line1": "Frozen: cannot act; Ghost Flash and Mountain Force end, Foresight and Main Character Halo cannot evade; immune to Burn and Stun.", "status.info.freeze.line2": "Each [Freeze] grants 15 Stance at turn start. At turn end, [Freeze] -1 and Stance -15; clearing Stance removes all Freeze.", "status.info.lostMind.line1": "100% resistance to Heart Demon.", "status.info.lostMind.line2": "Occasionally attacks itself.", "status.info.barrier.line1": "At turn end, gain {guard} Stance, then lose 1 stack.", "status.info.barrier.line2": "While [Barrier] remains, you are immune to Freeze, Burn, Stun, Qi Stagnation, Armor Break and Entangle.", "status.info.healing.line1": "At turn start, restore {hp} HP, then lose 1 [Healing].", "status.info.healing.line2": "", "status.info.concentration.line1": "At turn start, restore {sense} Sense, then lose 1 stack.", "status.info.concentration.line2": "Lose 1 stack whenever HP is lost.",
