    "event.rift.name": "Ravine", "event.rift.desc": "A ravine blocks your path.\nA bright red fruit grows in a crack in the cliff.\nYou cannot fly in this cave.\nWill you climb down for it?", "event.rift.try": "Try to pick it\n({chance}% success)",
    "event.corpse.name": "Nameless Corpse", "event.corpse.desc": "A corpse lies in the cave ahead.\nIts torn clothes bear the {sect} insignia.\nA storage bag lies nearby.", "event.sect.sword": "Hidden Sword Peak", "event.corpse.inspect": "Check the storage bag", "event.corpse.probe": "Inspect -2 Sense", "event.corpse.grab": "Reach in directly", "event.corpse.probeTrap": "Your Sense finds a self-destruct seal at the bag opening.\nYou withdraw your hand and leave.",
    "event.tablet.name": "Stone Stele", "event.tablet.desc": "A weathered stele stands deep in the cave.\nBlood-red runes are carved into it.", "event.tablet.study": "Focus and study -1 Sense\n({chance}% success)",
    "event.altar.name": "Bloodstained Altar", "event.altar.desc": "An altar stands in the cave.\nA stone disk rests at its center,\nwith a wolf-fang-shaped notch along its edge.", "event.altar.use": "Insert Great Wolf Fang", "event.altar.rest": "Meditate here\n(twice)", "event.altar.restResult": "Beneath the altar lies a rare Mystic-Metal ley line.\nYou sit cross-legged and meditate.",
    "event.firePit.name": "Fire Pit", "event.firePit.desc": "You pass a fire pit.\nAn ancient mirror seems to lie amid the flames below.", "event.firePit.useSilk": "Use Spider Silk\n(Consume Spider Silk ×5)", "event.firePit.useFrost": "Use Mystic Frost", "event.firePit.force": "Force your way to the treasure\n({chance}% success)",
    "event.firePit.silkNarrative": "You shoot spider silk around the ancient mirror.\nWith a tug, you pull it free and stow it in your bag.", "event.firePit.frostNarrative": "You cast a spell, sending icy mist from your fingertips.\nThe flames die out. You enter the pit and take the ancient mirror.", "event.firePit.forceSuccessNarrative": "You leap into the pit and seize the ancient mirror.", "event.firePit.gainMirror": "Obtained artifact [Yang-Spirit Mirror].", "event.firePit.forceFailureNarrative": "You twist your ankle and tumble into the fire pit.", "event.firePit.forceFailureSummary": "[Lose 4 HP]",
    "event.alchemy.name": "Alchemy", "event.alchemy.desc": "A medicinal scent fills the dim stone chamber.\nEarthfire burns beneath the furnace.\nA woman in a purple robe mixes herbs with her back to you.\nSuddenly she asks:\n“Have any Snake Slough?”", "event.alchemy.give": "Give her Snake Slough\n(Consume Snake Slough ×2)",
    "event.alchemy.giveNarrative": "You hand her what she asked for.\nShe crushes the Snake Slough and scatters it into the furnace.\nThe earthfire flares; the lid opens and over ten pills fly out.\nShe tosses you a bottle:\n“Yours.”", "event.alchemy.giveSummary": "[Gain Life-Locking Pill ×2]",
    "event.spiritVein.name": "Spirit Vein", "event.spiritVein.desc": "The path ends here.\nDense spiritual energy flows from deeper in the cave.\nYou dig through the earth and uncover a Spirit Stone vein.", "event.spiritVein.mine": "Mine", "event.spiritVein.rest": "Meditate here\n(three times)", "event.spiritVein.restResult": "You sit cross-legged and meditate.\nYou absorb the vast spiritual energy around you.",
    "event.rift.successNarrative": "You climb down and pick the fruit.\nYou swallow it. Heat surges through you, restoring all your blood essence.",
    "event.rift.successSummary": "[Restore all HP, Max HP +3]",
    "event.rift.failureNarrative": "You lose your footing and fall to the ravine floor.\nThere you find a hidden path and shake off your pursuers.",
    "event.rift.failureSummary": "[Lose {damage} HP]",
    "event.corpse.probeSafeNarrative": "Your Sense detects nothing amiss.\nYou erase the remaining seal and reach into the bag.",
    "event.corpse.lootSummary": "[Gain Spirit Stones ×{stones} and {manual} ×1]",
    "event.corpse.explosionNarrative": "As you touch the bag, its self-destruct seal activates.\nA burst of spiritual energy blasts you ten meters away.",
    "event.corpse.damageSummary": "[Lose {damage} HP]",
    "event.corpse.grabSafeNarrative": "You erase the remaining seal and reach into the bag.",
