    "status.fiveElementsSecret": "五行秘法", "status.windRaccoonBody": "風狸の体", "status.tianGangArmor": "天罡甲", "status.mainCharacterHalo": "主人公補正", "status.petrify": "石化", "status.darkForce": "暗勁", "status.burn": "灼焼", "status.entangle": "纏縛", "status.swordIntent": "剣意", "status.swordIntentGourd": "剣意瓢箪", "status.swordDomain": "無生剣域", "status.eightDirectionsWard": "八方鎮岳", "status.clearMind": "清明", "status.coldResistance": "耐寒", "status.steadfast": "不動", "status.heatResistance": "耐熱", "status.hardness": "堅硬", "status.reflection": "反震", "status.undying": "不死", "status.nirvana": "涅槃", "status.armorBreak": "破甲", "status.heartDemon": "心魔", "status.foresight": "予知", "status.qiStagnation": "気滞", "status.stun": "眩暈", "status.freeze": "冰凍", "status.lostMind": "失心", "status.barrier": "結界", "status.healing": "癒合", "status.concentration": "凝神",
    "status.info.qi.line1": "守勢より先にダメージを吸収し、罡気1で1ダメージを防ぐ。", "status.info.qi.line2": "保持者のターン開始時、現在の罡気は半減（切り捨て）。",
    "status.info.guard.line1": "罡気処理後、残りダメージが守勢以下なら完全に防ぐ。", "status.info.guard.line2": "守勢を超えると守勢は0になり超過分のみ受ける。自ターン開始時に0。",
    "status.info.burn.line1": "罡気と守勢を無視し、保持者のターン終了時に精血4を失う。", "status.info.burn.line2": "処理後、{downChance}%で【灼焼】-1、{upChance}%で【灼焼】+1。",
    "status.info.entangle.line1": "ターン開始時、{skipChance}%で今回の行動を飛ばす。ターン終了時に1層減少。", "status.info.entangle.line2": "火属性攻撃を受けると、全層が【灼焼】へ変換される。",
    "status.info.swordIntent.line1": "1層ごとに剣系攻撃のダメージ+1。", "status.info.swordIntent.line2": "保持者のターン終了時【剣意】-1。",
    "status.info.fiveElementsSecret.line1": "五行門修士だけが使う秘法。", "status.info.fiveElementsSecret.line2": "冰凍・灼焼・眩暈・気滞・破甲・纏縛への耐性を25%高め、法力の巡りを速める。", "status.info.windRaccoonBody.line1": "精血が0になった時、直ちに精血{hp}を回復する。法力が尽きている時は発動しない。", "status.info.windRaccoonBody.line2": "", "status.info.tianGangArmor.line1": "護身法宝。毎ターン開始時に罡気{qi}を得る。", "status.info.tianGangArmor.line2": "", "status.info.mainCharacterHalo.line1": "隠し効果。", "status.info.mainCharacterHalo.line2": "", "status.info.petrify.line1": "ターン終了時に守勢{guard}を得る。", "status.info.petrify.line2": "", "status.info.darkForce.line1": "ターン終了時に1層減少。", "status.info.darkForce.line2": "【暗勁】が消滅した時、精血を{damage}失う。", "status.info.swordIntentGourd.line1": "蔵剣峰修士だけが持つ本命法宝。", "status.info.swordIntentGourd.line2": "気滞耐性を50%高め、剣意の流失を防ぐ。",
    "status.info.swordDomain.line1": "ターン開始時、{damage}を失い、自身は{qi}と{intent}を得る。", "status.info.swordDomain.line2": "", "status.info.eightDirectionsWard.line1": "ターン開始時に罡気8を得る。", "status.info.eightDirectionsWard.line2": "", "status.info.clearMind.line1": "眩暈耐性50%。", "status.info.clearMind.line2": "心魔耐性50%。", "status.info.coldResistance.line1": "冰凍耐性75%。", "status.info.coldResistance.line2": "ターン終了時に【冰凍】をすべて解除。", "status.info.steadfast.line1": "眩暈耐性75%。", "status.info.steadfast.line2": "ターン終了時に【眩暈】をすべて解除。", "status.info.heatResistance.line1": "灼焼耐性75%、さらに受ける灼焼ダメージが半減。", "status.info.heatResistance.line2": "", "status.info.hardness.line1": "破甲耐性75%、さらに受ける実ダメージが25%減少。", "status.info.hardness.line2": "", "status.info.reflection.line1": "実際に失った精血の{percent}%を攻撃者へ反震ダメージとして返す。", "status.info.reflection.line2": "ターン開始時に全消去。", "status.info.undying.line1": "精血が0になった時、直ちに精血{hp}を回復し、全状態を解除した後、罡気{qi}を得る。", "status.info.undying.line2": "", "status.info.nirvana.line1": "灼焼ダメージで精血が0になった時、直ちに精血1を回復し、すべての状態を解除する。", "status.info.nirvana.line2": "解除した【灼焼】1層ごとにさらに精血20を回復し、法力2を得る。",
    "status.info.armorBreak.line1": "存在中は守勢が常に0となり、守勢を得られず、実際に受けるダメージが50%増加する。", "status.info.armorBreak.line2": "ターン終了時【破甲】-1。",
    "status.info.heartDemon.line1": "ターン開始時に一定確率で心魔が発作し、現在の神識が低いほど確率が上がる。", "status.info.heartDemon.line2": "心魔の発作は行動を乱し、損害を与える。発作後【心魔】-1。",
    "status.info.foresight.line1": "敵の攻撃1回と、その付随状態を回避する。", "status.info.foresight.line2": "保持者のターン開始時【予知】-1。",
    "status.info.qiStagnation.line1": "ターン開始時の法力回復を停止し、罡気の流失を加速する。", "status.info.qiStagnation.line2": "ターン終了時に1層減少。",
    "status.info.stun.line1": "獲得時に守勢を0にし、鬼閃と崩山勁を解除。眩暈中は予知と主人公補正の回避が発動せず、ターン開始時に行動を飛ばす。", "status.info.stun.line2": "【眩暈】1層ごとに眩暈耐性+25%。保持者のターン終了時に1層減少。",
    "status.info.freeze.line1": "冰凍中は行動不能。鬼閃と崩山勁は直ちに解除され、予知と主人公補正の回避は発動しない。灼焼と眩暈を受けない。", "status.info.freeze.line2": "ターン開始時に【冰凍】1層ごとに守勢15を得る。終了時に【冰凍】-1、守勢-15。守勢が0になると全解除。", "status.info.lostMind.line1": "心魔耐性100%。", "status.info.lostMind.line2": "時折、自分自身を攻撃する。", "status.info.barrier.line1": "ターン終了時に守勢{guard}を得て、その後1層減少。", "status.info.barrier.line2": "【結界】が存在する間、冰凍・灼焼・眩暈・気滞・破甲・纏縛を無効化。", "status.info.healing.line1": "ターン開始時に精血{hp}を回復し、その後【癒合】-1。", "status.info.healing.line2": "", "status.info.concentration.line1": "ターン開始時に神識{sense}を回復し、その後1層減少。", "status.info.concentration.line2": "精血を失うと1層減少。",
